package net.officefloor.hq.app.period;

import java.util.Map;

/**
 * A period on a sheet: its name and its from and to date (yyyy-MM-dd), inclusive, whether it is closed, and its
 * due-total fixed when closed (two decimals; null while open), and each person's due-total for it fixed then (by person
 * id, two decimals; empty while open — a person added since has none), and whether it is soft-closed instead: its
 * figures fixed the same way, but claims due inside it may still be added, edited and change status; and the most OPEN
 * or PENDING claims a person may have in it (null for no cap); and each person's carried figure for it fixed when it was
 * (soft-)closed (by person id, two decimals; empty while open); and each person's opening balance for it, added to their
 * carried figure (by person id, two decimals; none for a person with no opening).
 */
public record Period(String name, String from, String to, boolean closed, String closedTotal,
        Map<Long, String> closedPeople, boolean soft, Integer cap, Map<Long, String> closedCarried,
        Map<Long, String> openings) {

    /** Whether its figures are fixed: closed or soft-closed. */
    public boolean fixed() {
        return closed || soft;
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.role.Roles;
import net.officefloor.hq.app.setting.Settings;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Reopens a closed or soft-closed period: its fixed due-total is dropped, so it totals its claims' current figures again. Only a
 * role the permission matrix lets (by default a steward) may; refuses anyone else, a period not on the sheet, or one not closed.
 */
public class ReopenPeriod {
    public void reopen(@PathVariable("sheet") String sheet, @PathVariable("period") String period,
            @RequestParam("user") String user, Periods periods, Roles roles, Settings settings, Audit audit)
            throws InvalidPeriodException {
        if (!settings.permits(sheet, "reopen", roles.of(sheet, user))) {
            throw new InvalidPeriodException("Your role may not reopen a period");
        }
        Period found = periods.find(sheet, period);
        if (found == null) {
            throw new InvalidPeriodException("There is no period named " + period);
        }
        if (!found.fixed() || !periods.reopen(sheet, period)) {
            throw new InvalidPeriodException("The period " + period + " is not closed");
        }
        audit.record("PERIOD_REOPENED sheet=" + sheet + " by=" + user + " period=" + period);
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.role.Roles;
import net.officefloor.hq.app.setting.Settings;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Closes the period, fixing its due-total now, and each person's on the sheet (the part of it from their claims): the due now of the claims whose due-by falls in it
 * that counted at the end of its last day (OPEN, PENDING and SETTLED then by their status log, but not a deferred one, nor an unbound open one dated
 * within its person's hold) (a
 * claim with no rate adds nothing). Refuses a role the permission matrix does not let close, a period not on the sheet or one already closed.
 */
public class ClosePeriod {
    public void close(@PathVariable("sheet") String sheet, @PathVariable("period") String period,
            @RequestParam("user") String user, Periods periods, PeriodCloser closer, Settings settings,
            Roles roles)
            throws InvalidPeriodException {
        if (!settings.permits(sheet, "close", roles.of(sheet, user))) {
            throw new InvalidPeriodException("Your role may not close a period");
        }
        Period found = periods.find(sheet, period);
        if (found == null) {
            throw new InvalidPeriodException("There is no period named " + period);
        }
        if (found.closed()) {
            throw new InvalidPeriodException("The period " + period + " is already closed");
        }
        if (!closer.close(sheet, user, found, false)) {
            throw new InvalidPeriodException("The period " + period + " is already closed");
        }
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.Late;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Dated;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.SheetClock;
import org.springframework.stereotype.Service;

/**
 * Closes a period, fixing its due-total now, and each person's on the sheet (the part of it from their claims): the due now of the claims whose due-by falls in it
 * that counted at the end of its last day (OPEN, PENDING and SETTLED then by their status log, but not a deferred one, nor an unbound open one dated
 * within its person's hold) (a claim with no rate adds nothing); and each person's carried figure for it: the due now of
 * their claims that count at its end whose due-by falls in an earlier period (one ending before it starts) and that were
 * still OPEN or PENDING at its end by their status log, plus their opening balance for it. Shared by a close by hand and the auto close of a today change.
 */
@Service
public class PeriodCloser {

    private final Periods periods;
    private final Claims claims;
    private final People people;
    private final Rates rates;
    private final Settings settings;
    private final SheetClock clock;
    private final Audit audit;

    public PeriodCloser(Periods periods, Claims claims, People people, Rates rates, Settings settings, SheetClock clock,
            Audit audit) {
        this.periods = periods;
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.settings = settings;
        this.clock = clock;
        this.audit = audit;
    }

    /** Closes the period found open on the sheet; false when it was already closed. An auto close is audited auto=yes. */
    public boolean close(String sheet, String user, Period found, boolean auto) {
        return close(sheet, user, found, auto, false);
    }

    /**
     * Closes the period found open (or soft-closed) on the sheet, or soft-closes it, fixing its figures afresh; false
     * when it was already closed, or for a soft close already soft-closed.
     */
    public boolean close(String sheet, String user, Period found, boolean auto, boolean soft) {
        LocalDate from = LocalDate.parse(found.from());
        LocalDate to = LocalDate.parse(found.to());
        Map<Long, Person> byId = people.list(sheet).stream().collect(Collectors.toMap(Person::id, (p) -> p));
        List<Rate> sheetRates = rates.list(sheet);
        Dated floor = settings.floor(sheet);
        Late late = settings.late(sheet, clock.today(sheet));
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        Map<Long, BigDecimal> perPerson = new LinkedHashMap<>();
        byId.keySet().forEach((id) -> perPerson.put(id, BigDecimal.ZERO.setScale(2)));
        Map<Long, BigDecimal> carried = new LinkedHashMap<>(perPerson);
        periods.openings(sheet, found.name()).forEach((id, amount) -> {
            if (carried.containsKey(id)) {
                carried.merge(id, amount, BigDecimal::add);
            }
        });
        List<Period> sheetPeriods = periods.list(sheet);
        List<Claim> sheetClaims = claims.list(sheet);
        for (Claim claim : sheetClaims) {
            Person person = byId.get(claim.person());
            LocalDate dueBy = LocalDate.parse(claim.dueBy());
            boolean earlier = sheetPeriods.stream().anyMatch((p) -> !dueBy.isBefore(LocalDate.parse(p.from()))
                    && !dueBy.isAfter(LocalDate.parse(p.to())) && LocalDate.parse(p.to()).isBefore(from));
            ClaimStatus then = claim.statusOn(to);
            if (person == null || !earlier || (then != ClaimStatus.OPEN && then != ClaimStatus.PENDING)
                    || !person.countsOn(claim, to)) {
                continue;
            }
            BigDecimal due = claim.due(sheetRates, person.gradeOn(claim.date()), floor, late);
            if (due != null) {
                carried.merge(person.id(), due, BigDecimal::add);
            }
        }
        for (Claim claim : sheetClaims) {
            LocalDate date = LocalDate.parse(claim.dueBy());
            Person person = byId.get(claim.person());
            if (person == null || !person.countsOn(claim, to) || date.isBefore(from) || date.isAfter(to)) {
                continue;
            }
            BigDecimal due = claim.due(sheetRates, person.gradeOn(claim.date()), floor, late);
            if (due != null) {
                total = total.add(due);
                perPerson.merge(person.id(), due, BigDecimal::add);
            }
        }
        if (!periods.close(sheet, found.name(), total, perPerson, carried, soft)) {
            return false;
        }
        audit.record((soft ? "PERIOD_SOFT_CLOSED" : "PERIOD_CLOSED") + " sheet=" + sheet + " by=" + user + " period=" + found.name() + " total="
                + total.toPlainString() + (auto ? " auto=yes" : ""));
        return true;
    }

    /**
     * Closes, in order of their to-dates, every open (neither closed nor soft-closed) period of the sheet whose to-date plus the grace days is before
     * the sheet's today; none when the sheet has no grace days.
     */
    public void autoClose(String sheet, String user) {
        Integer grace = settings.graceDays(sheet);
        if (grace == null) {
            return;
        }
        LocalDate today = clock.today(sheet);
        List<Period> due = periods.list(sheet).stream()
                .filter((p) -> !p.fixed() && LocalDate.parse(p.to()).plusDays(grace).isBefore(today))
                .sorted(Comparator.comparing(Period::to)).toList();
        for (Period period : due) {
            close(sheet, user, period, true);
        }
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** The periods kept per sheet. */
@Repository
public class Periods {

    private static final RowMapper<Period> ROW = (rs, i) -> new Period(rs.getString("name"),
            rs.getDate("from_date").toLocalDate().toString(), rs.getDate("to_date").toLocalDate().toString(),
            rs.getBoolean("closed"),
            rs.getBigDecimal("closed_total") == null ? null : rs.getBigDecimal("closed_total").toPlainString(),
            Map.of(), rs.getBoolean("soft"), (Integer) rs.getObject("claim_cap"), Map.of(), Map.of());

    private static final String COLUMNS = "SELECT name, from_date, to_date, closed, closed_total, soft, claim_cap FROM period";

    private final JdbcTemplate jdbc;

    public Periods(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every period on the sheet, by from-date. */
    public List<Period> list(String sheet) {
        return jdbc.query(COLUMNS + " WHERE sheet = ? ORDER BY from_date", ROW, sheet).stream()
                .map((p) -> withOpenings(sheet, withPeople(sheet, p))).toList();
    }

    /** The period with its people's opening balances. */
    private Period withOpenings(String sheet, Period period) {
        Map<Long, String> openings = new LinkedHashMap<>();
        jdbc.query("SELECT person, amount FROM period_opening WHERE sheet = ? AND period = ? ORDER BY person",
                (rs) -> {
                    openings.put(rs.getLong("person"), rs.getBigDecimal("amount").toPlainString());
                }, sheet, period.name());
        return new Period(period.name(), period.from(), period.to(), period.closed(), period.closedTotal(),
                period.closedPeople(), period.soft(), period.cap(), period.closedCarried(), openings);
    }

    /** Each person's opening balance for the period (by person id); none for a person with no opening. */
    public Map<Long, BigDecimal> openings(String sheet, String name) {
        Map<Long, BigDecimal> openings = new LinkedHashMap<>();
        jdbc.query("SELECT person, amount FROM period_opening WHERE sheet = ? AND period = ?",
                (rs) -> {
                    openings.put(rs.getLong("person"), rs.getBigDecimal("amount"));
                }, sheet, name);
        return openings;
    }

    /** Adds the amount to the person's opening balance for the period. */
    public void addOpening(String sheet, String name, long person, BigDecimal amount) {
        if (jdbc.update("UPDATE period_opening SET amount = amount + ? WHERE sheet = ? AND period = ? AND person = ?",
                amount, sheet, name, person) == 0) {
            jdbc.update("INSERT INTO period_opening (sheet, period, person, amount) VALUES (?, ?, ?, ?)", sheet, name,
                    person, amount);
        }
    }

    /** The period with its people's due-totals and carried figures fixed when it was closed. */
    private Period withPeople(String sheet, Period period) {
        if (!period.fixed()) {
            return period;
        }
        Map<Long, String> people = new LinkedHashMap<>();
        Map<Long, String> carried = new LinkedHashMap<>();
        jdbc.query("SELECT person, total, carried FROM period_person_total WHERE sheet = ? AND period = ? ORDER BY person",
                (rs) -> {
                    people.put(rs.getLong("person"), rs.getBigDecimal("total").toPlainString());
                    carried.put(rs.getLong("person"), rs.getBigDecimal("carried").toPlainString());
                }, sheet, period.name());
        return new Period(period.name(), period.from(), period.to(), period.closed(), period.closedTotal(), people,
                period.soft(), period.cap(), carried, period.openings());
    }

    /** The sheet's period of the name, or null when there is none. */
    public Period find(String sheet, String name) {
        List<Period> found = jdbc.query(COLUMNS + " WHERE sheet = ? AND name = ?", ROW, sheet, name);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether the date falls inside a closed period of the sheet. */
    public boolean closedOn(String sheet, LocalDate date) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM period WHERE sheet = ? AND closed AND from_date <= ? AND to_date >= ?",
                Integer.class, sheet, Date.valueOf(date), Date.valueOf(date));
        return n != null && n > 0;
    }

    /** Whether the date falls inside a soft-closed period of the sheet. */
    public boolean softClosedOn(String sheet, LocalDate date) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM period WHERE sheet = ? AND soft AND from_date <= ? AND to_date >= ?",
                Integer.class, sheet, Date.valueOf(date), Date.valueOf(date));
        return n != null && n > 0;
    }

    /** The name of the sheet's period the date falls inside, or null when it is in none. */
    public String nameOn(String sheet, LocalDate date) {
        List<String> found = jdbc.queryForList("SELECT name FROM period WHERE sheet = ? AND from_date <= ? AND to_date >= ?",
                String.class, sheet, Date.valueOf(date), Date.valueOf(date));
        return found.isEmpty() ? null : found.get(0);
    }

    /** The sheet's period the date falls inside, or null when it is in none. */
    public Period on(String sheet, LocalDate date) {
        List<Period> found = jdbc.query(COLUMNS + " WHERE sheet = ? AND from_date <= ? AND to_date >= ?", ROW, sheet,
                Date.valueOf(date), Date.valueOf(date));
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether the sheet has a period of the name. */
    public boolean named(String sheet, String name) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet = ? AND name = ?", Integer.class,
                sheet, name);
        return n != null && n > 0;
    }

    /** Whether any period on the sheet shares a date with the inclusive range. */
    public boolean overlaps(String sheet, PeriodInput input) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM period WHERE sheet = ? AND from_date <= ? AND to_date >= ?", Integer.class,
                sheet, Date.valueOf(input.to()), Date.valueOf(input.from()));
        return n != null && n > 0;
    }

    public void add(String sheet, PeriodInput input) {
        jdbc.update("INSERT INTO period (sheet, name, from_date, to_date, claim_cap) VALUES (?, ?, ?, ?, ?)", sheet,
                input.name(), Date.valueOf(input.from()), Date.valueOf(input.to()), input.cap());
    }

    /**
     * Closes the period (or soft-closes it) with its due-total and each person's due-total and carried figure (by id)
     * fixed afresh; false when it was
     * already closed, or for a soft close already soft-closed (or is gone). Closing a soft-closed period is allowed.
     */
    public boolean close(String sheet, String name, BigDecimal total, Map<Long, BigDecimal> people,
            Map<Long, BigDecimal> carried, boolean soft) {
        String sql = soft
                ? "UPDATE period SET soft = TRUE, closed_total = ? WHERE sheet = ? AND name = ? AND NOT closed AND NOT soft"
                : "UPDATE period SET closed = TRUE, soft = FALSE, closed_total = ? WHERE sheet = ? AND name = ? AND NOT closed";
        if (jdbc.update(sql, total, sheet, name) != 1) {
            return false;
        }
        jdbc.update("DELETE FROM period_person_total WHERE sheet = ? AND period = ?", sheet, name);
        people.forEach((person, due) -> jdbc.update(
                "INSERT INTO period_person_total (sheet, period, person, total, carried) VALUES (?, ?, ?, ?, ?)", sheet,
                name, person, due, carried.getOrDefault(person, BigDecimal.ZERO.setScale(2))));
        return true;
    }

    /** Reopens the closed or soft-closed period, dropping its fixed due-totals and carried figures; false when it was neither (or is gone). */
    public boolean reopen(String sheet, String name) {
        if (jdbc.update("UPDATE period SET closed = FALSE, soft = FALSE, closed_total = NULL WHERE sheet = ? AND name = ?"
                + " AND (closed OR soft)",
                sheet, name) != 1) {
            return false;
        }
        jdbc.update("DELETE FROM period_person_total WHERE sheet = ? AND period = ?", sheet, name);
        return true;
    }
}
